sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        g_form.clearValue('u_requested_for_email');
        return;
    }

    // 关键：打印请求地址和参数，排查格式问题
    var restUrl = '/api/x_58872_needit/get_user_email_api/get/' + newValue;
//	g_form.addInfoMessage('restUrl: '+restUrl);
    console.log('【请求地址】', restUrl); // 查看控制台输出的地址是否正确
    console.log('【用户ID参数】', newValue); // 确认newValue是32位sys_id

    var xhr = new XMLHttpRequest();
    xhr.open('GET', restUrl, true);
    xhr.setRequestHeader('Accept', 'application/json');
    xhr.setRequestHeader('X-UserToken', g_ck);
    xhr.withCredentials = true;

    xhr.onload = function() {
	//	g_form.addInfoMessage('xhr.status: '+xhr.status);
	//	g_form.addInfoMessage('xhr.responseText: '+xhr.responseText);
        // console.log('【响应状态码】', xhr.status);
        // console.log('【响应内容】', xhr.responseText); // 打印服务端返回的错误信息
        if (xhr.status === 200) {
            var result = JSON.parse(xhr.responseText);
		//	g_form.addInfoMessage('result: '+result);
			// g_form.addInfoMessage('result.email: '+result.result.email);
             g_form.setValue('u_requested_for_email', result.result.email);
        } else {
            g_form.clearValue('u_requested_for_email');
            console.error('请求失败：', xhr.statusText);
        }
    };
    xhr.onerror = function() {
        g_form.clearValue('u_requested_for_email');
        console.error('网络异常');
    };
    xhr.send();
}
